			}
		}
	}
	return context.WithValue(ctx, dataCtxKey, newData)
}

func DataFromContext(ctx context.Context) map[string]any {
	value := ctx.Value(dataCtxKey)
	if value == nil {
		return nil
	}
	return value.(map[string]any)
}
